import{_ as t,C as r,o as a,c as n,a3 as c,E as m,w as l,j as e}from"./chunks/framework.BXPnjTLK.js";const d="/versions/v0.19.92/screens/perform/macro_rows_sysex.png",i="/versions/v0.19.92/screens/perform/single_macro_sysex.png",h="/versions/v0.19.92/screens/perform/two_macros_sysex.png",p="/versions/v0.19.92/screens/perform/single_macro_sysex_named.png",E=JSON.parse('{"title":"SysEx on Perform","description":"","frontmatter":{},"headers":[],"relativePath":"perform/macro-rows/sysex.md","filePath":"perform/macro-rows/sysex.md"}'),g={name:"perform/macro-rows/sysex.md"};function x(y,s,_,f,u,S){const o=r("ManualRelated");return a(),n("div",null,[s[1]||(s[1]=c('<h1 id="sysex-on-perform" tabindex="-1">SysEx on Perform <a class="header-anchor" href="#sysex-on-perform" aria-label="Permalink to &quot;SysEx on Perform&quot;">​</a></h1><p><strong>SysEx</strong> macros send a custom MIDI System Exclusive message from the knob. On Perform they show <strong><code>SYX</code></strong> plus the <strong>message length</strong> — no controller numbers, no channel.</p><p><img src="'+d+'" alt="SysEx macro rows on Perform" class="screen"></p><h2 id="what-to-expect-on-the-row" tabindex="-1">What to expect on the row <a class="header-anchor" href="#what-to-expect-on-the-row" aria-label="Permalink to &quot;What to expect on the row&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Part of row</th><th>SysEx macro</th></tr></thead><tbody><tr><td>Message type</td><td><code>SYX</code></td></tr><tr><td>Message length</td><td><strong>6 BYTES</strong> — how many bytes the knob sends (0–16)</td></tr><tr><td>Outputs</td><td><code>U</code> / <code>1</code> / <code>2</code></td></tr><tr><td>Live value</td><td>14-bit level mapped into the message bytes</td></tr></tbody></table><p>The length is the same number the <a href="./../../macros/sysex">SysEx macro grid</a> shows. An empty message reads <strong>0 BYTES</strong> and sends nothing.</p><p>With <strong>one</strong> macro on, <strong>SYX</strong> is large and the length sits on the lower line.</p><p><img src="'+i+'" alt="Single-macro SysEx" class="screen"></p><p>With <strong>two</strong> macros on, each row keeps the mode name on the upper line and the length (plus outputs) on the lower line.</p><p><img src="'+h+'" alt="Two-macro SysEx" class="screen"></p><h2 id="name-a-sysex-control" tabindex="-1">Name a SysEx control <a class="header-anchor" href="#name-a-sysex-control" aria-label="Permalink to &quot;Name a SysEx control&quot;">​</a></h2><p>Like other classic MIDI macros, a SysEx macro can have a <strong>custom name</strong>. On the four-row and three-macro layouts the name follows <strong>SYX 6 BYTES</strong>; on packed 1- and 2-macro views the name is large and the lower line reads <strong>SYX 6 BYTES</strong>. There is still no channel.</p><p><img src="'+p+'" alt="Named single-macro SysEx" class="screen"></p><p>Build your message in <a href="./../edit-mode">edit mode</a> with the <a href="./../../macros/sysex">SysEx macro grid</a> and <a href="./../../macros/sysex-editor">SysEx editor</a>.</p>',14)),m(o,null,{default:l(()=>[...s[0]||(s[0]=[e("ul",null,[e("li",null,[e("a",{href:"./classic-midi"},"Classic MIDI macro rows")]),e("li",null,[e("a",{href:"./../../macros/sysex"},"SysEx macro mode")]),e("li",null,[e("a",{href:"./../../macros/sysex-editor"},"SysEx editor")])],-1)])]),_:1})])}const b=t(g,[["render",x]]);export{E as __pageData,b as default};
